// Exports a generic function that narrows an object's type to specified keys.
export const pickKeys = <T, K extends keyof T = keyof T>(obj: T, ...keys: K[]): Pick<T, K> => {
	// Uses reduce to iterate through the requested keys and build a new object.
	return keys.reduce((acc, key) => {
		// Checks if the current key actually exists in the original object to avoid undefined values.
		if (hasKey(obj, key)) {
			// Copies the value from the original object to the accumulator under the current key.
			acc[key] = obj[key];
		}
		// Returns the accumulated object for the next iteration or final result.
		return acc;
	// Initializes the accumulator as an empty object typed with the picked keys.
	}, {} as Pick<T, K>);
};
```

